import{z as l,x as A,o,c as d,q as t,j as s,D as E,d as r,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"安全经济学","description":"","frontmatter":{"title":"安全经济学","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/security-economics.md","filePath":"cs/security-economics.md","lastUpdated":1791413859000}'),p={name:"cs/security-economics.md"};function c(m,a,u,h,D,f){const n=A("Mermaid");return o(),d("div",null,[a[2]||(a[2]=t('<h1 id="安全经济学" tabindex="-1">安全经济学 <a class="header-anchor" href="#安全经济学" aria-label="Permalink to &quot;安全经济学&quot;">​</a></h1><div class="epigraph"><p>漏洞留下往往因为谁承担损失、谁承担修补成本不对齐。Anderson 问：激励，而不只是算法。补丁窗口、 visiblity、责任构成市场。</p><footer>—— Anderson, Why Information Security is Hard, ACSAC 2001；Anderson and Moore, The Economics of Information Security, Science 2006</footer></div><p>上一课<a href="/cs/tor-onion-routing">Tor</a>依赖志愿者中继，而志愿者为什么不散、为什么总是不够，本身就是经济学问题。本课的缺口是<strong>激励</strong>：谁付钱改进安全。课程接到金融栏的激励主题，但不进限价簿。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核心失灵是负外部性：软件出事，损失大多落在用户与被波及的第三方，厂商只承担一小块，于是「修得更安全」的投资长期低于社会最优——漏洞留下，不是因为没人会修。缺口是四类改对齐的机制：责任分配、网络风险保险、披露政策、赏金市场。<span class="marginnote">「负外部性」翻译成大白话：做决策的人不用承担决策的全部代价——厂商决定「这个洞下个版本再说」，出事赔钱的却是用户和被波及的其他公司；只要这个差价存在，理性的厂商就会持续少修。</span></p><h3 id="不是量化定价课" tabindex="-1">不是量化定价课 <a class="header-anchor" href="#不是量化定价课" aria-label="Permalink to &quot;不是量化定价课&quot;">​</a></h3><p>本课不是量化定价课：不把 CAPM 或限价簿搬进来，只谈安全主体的激励结构。</p><p><span class="marginnote">Anderson 2001/2006。可用安全下一课谈人。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法拿两极对照：公地悲剧一极——共享生态里各自搭便车，没人维护公共安全；赏金市场另一极——给发现漏洞定价，把外部性变成收入。现实政策在两极之间滑动：强制披露时限、保险定价、按责任判赔。下一课可用安全。</p>',11)),(o(),s(i,null,{default:E(()=>[B(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COST%5B%22%E4%BF%AE%E8%A1%A5%E6%88%90%E6%9C%AC%22%5D%20--%3E%20WHO%5B%22%E7%94%B1%E8%B0%81%E6%89%BF%E6%8B%85%22%5D%0A%20%20LOSS%5B%22%E4%BA%8B%E6%95%85%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20WHO2%5B%22%E7%94%B1%E8%B0%81%E6%89%BF%E6%8B%85%22%5D%0A%20%20WHO%20--%3E%20GAP%5B%22%E4%B8%8D%E5%AF%B9%E9%BD%90%E5%88%99%E6%B4%9E%E7%95%99%E4%B8%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制是：技术控制在激励错位时会被关闭——厂商默认配置向易用倾斜，管理员为保可用性关掉告警，因为事故成本不落在决策者头上。赏金与责任是改变支付流向的机制，不是道德说教：bounty 定价之后，白帽的时间机会成本被覆盖，漏洞流入修复流程而非黑市。可用安全下一课：用户也会关。",-1)),a[5]||(a[5]=e("p",null,"赏金机制改变的是发现者面前的支付表：同一个漏洞，两条出口的流向完全不同。",-1)),(o(),s(i,null,{default:E(()=>[B(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIND%5B%22%E7%99%BD%E5%B8%BD%E5%8F%91%E7%8E%B0%E6%BC%8F%E6%B4%9E%22%5D%20--%3E%20CH%7B%22%E6%8A%A5%E5%91%8A%E5%8D%96%E7%BB%99%E8%B0%81%3F%22%7D%0A%20%20CH%20--%20%22%E9%BB%91%E5%B8%82%20%2F%20%E6%BC%8F%E6%B4%9E%E7%BB%8F%E7%BA%AA%22%20--%3E%20DARK%5B%22%E6%B5%81%E5%85%A5%E6%94%BB%E5%87%BB%E9%93%BE%22%5D%0A%20%20CH%20--%20%22%E5%AE%98%E6%96%B9%E8%B5%8F%E9%87%91%E9%A1%B9%E7%9B%AE%22%20--%3E%20BOUNTY%5B%22%E9%A2%86%E8%B5%8F%20%2B%20%E5%8E%82%E5%95%86%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20BOUNTY%20--%3E%20REP%5B%22%E5%A3%B0%E8%AA%89%E4%B8%8E%E8%A6%86%E7%9B%96%E8%AE%B0%E5%BD%95%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20REP%20--%3E%20MORE%5B%22%E5%90%8E%E7%BB%AD%E5%8F%91%E7%8E%B0%E8%80%85%E6%9B%B4%E5%80%BE%E5%90%91%E5%AE%98%E6%96%B9%E6%B8%A0%E9%81%93%22%5D%0A%20%20DARK%20-.%20%22%E6%8D%9F%E5%A4%B1%E7%94%B1%E8%B0%81%E6%89%BF%E6%8B%85%3F%22%20.-%3E%20VICTIM%5B%22%E7%94%A8%E6%88%B7%E4%B8%8E%E7%AC%AC%E4%B8%89%E6%96%B9%E4%B9%B0%E5%8D%95%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">数字实例：头部厂商的严重漏洞赏金常为数万美元一次，相当于一名工程师数月薪资——赏金定价的意义就在于覆盖白帽的时间机会成本，让他把报告送进修复流程比卖给黑市「划算」，机制替代了道德呼吁。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不进量化微观结构；边界要点名：激励机制的度量本身困难——事故稀有、归因混乱，保险定价常靠类比而非数据支撑。可用安全下一课。</p><p><span class="marginnote">常见误区：初学者容易以为「漏洞存在 = 团队不会修」——Anderson 的论点恰恰相反：会修的人一直都在，缺的是让「修补的收益落到修补者头上」的支付结构；所以解决办法换机制（责任、赏金、保险），而不是换一批更努力的工程师。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Tor 靠激励维持中继；一般安全也靠激励。</li><li>损失与修补不对齐则洞留下。</li><li>赏金与责任是机制，不是道德说教。</li><li>下一课可用安全。</li><li>出处：Anderson, 2001；Anderson and Moore, 2006。</li></ul>',6))])}const F=l(p,[["render",c]]);export{T as __pageData,F as default};
